    cost_breakdown, 
    '{disposal,disposal_method}', 
    '"Hazardous Waste"'
) WHERE cost_breakdown->'disposal'->>'disposal_method' = 'Recycle' 
AND CAST(cost_breakdown->'sustainability'->>'carbon_footprint' AS numeric) > 50;

